function cap(team,year,venue,postseason){
  var C=window.KBO_CAPS, t=C.teams[team];
  if(postseason&&venue){var pv=''+venue;for(var n in (C.ps_venues||{})){if(pv.indexOf(n)>=0)return C.ps_venues[n];}}
  if(postseason&&t&&t.postseason!=null){var ps=t.postseason;
    if(typeof ps==='number')return ps;
    var yy=parseInt(year)||9999;
    for(var j=0;j<ps.length;j++){var q=ps[j];
      if((q.min==null||yy>=q.min)&&(q.max==null||yy<=q.max))return q.cap;}}
  if(venue){var v=''+venue;for(var k in C.venues){if(v.indexOf(k)>=0)return C.venues[k];}}
  if(!t)return C.default_cap||20000;
  var y=parseInt(year)||9999;
  for(var i=0;i<t.eras.length;i++){var e=t.eras[i];
    if((e.min==null||y>=e.min)&&(e.max==null||y<=e.max))return e.cap;}
  return t.eras[t.eras.length-1].cap;
}
